    const value = current().value;
    return value === '<' || value === '<=' || value === '>' ||
      value === '>=' || value === '==' || value === '!=';
  }

  function comparison() {
    const left = sum();
    if (!isComparison()) return left;
    const operands = [left];
    const operators = [];
    while (isComparison()) {
      operators.push(take());
      operands.push(sum());
