  const cases = [
    ['3 < 2 < 1', false],
    ['1 < 2 <= 2 != 3 == 3 >= 2 > 1', true],
    ['1 == 1 == 1', true],
    ['3 > 2 > 1', true],
    ['1 + 2 < 2 * 2', true],
    ['(3 > 2) == 1', true],
    ['(3 < 2) == 0', true],
    ['(3 > 2) + (3 < 2)', 1],
    ['-(1 < 2) ** 2', -1],
    ['abs(1 > 2)', 0],
    ['min(1 < 2, 2)', 1],
    ['(1 < 2) < 2', true],
